  "name": "ActEmergence.tsx",
  "path": "ActEmergence.tsx",
  "content": "import { addPropertyControls, ControlType, useIsStaticRenderer } from "framer"
import { useEffect, useRef, useState, type CSSProperties } from "react"

interface Props {
    style?: CSSProperties
}

function clamp(v: number, a: number, b: number) {
    return Math.max(a, Math.min(b, v))
}

/**
 * @framerSupportedLayoutWidth fixed
 * @framerSupportedLayoutHeight fixed
 */
export default function ActEmergence(props: Props) {
    const { style } = props
    const isStatic = useIsStaticRenderer()
    const sectionRef = useRef<HTMLDivElement>(null)
    const [progress, setProgress] = useState(isStatic ? 1 : 0)
    const [inView, setInView] = useState(false)

    useEffect(() => {
        if (isStatic) return
        const el = sectionRef.current
        if (!el) return
        const io = new IntersectionObserver(
            ([entry]) => setInView(entry.isIntersecting),
            { threshold: 0 }
        )
        io.observe(el)
        return () => io.disconnect()
    }, [isStatic])

    useEffect(() => {
        if (isStatic) return
        const handleScroll = () => {
            const el = sectionRef.current
            if (!el) return
            const rect = el.getBoundingClientRect()
            const vh = window.innerHeight
            // progress 0..1 while the section traverses the viewport
            const total = rect.height - vh
            const raw = total > 0 ? -rect.top / total : 0
            setProgress(clamp(raw, 0, 1))
        }
        handleScroll()
        window.addEventListener("scroll", handleScroll, { passive: true })
        window.addEventListener("resize", handleScroll)
        return () => {
            window.removeEventListener("scroll", handleScroll)
            window.removeEventListener("resize", handleScroll)
        }
    }, [isStatic])

    // Stagger three rings based on scroll progress
    const ring1 = clamp(progress / 0.35, 0, 1) // 0 → 0.35
    const ring2 = clamp((progress - 0.2) / 0.35, 0, 1) // 0.2 → 0.55
    const ring3 = clamp((progress - 0.4) / 0.35, 0, 1) // 0.4 → 0.75
    const core = clamp((progress - 0.55) / 0.3, 0, 1) // 0.55 → 0.85

    // Text reveals timed to progress
    const titleReveal = clamp((progress - 0.1) / 0.25, 0, 1)
    const italicReveal = clamp((progress - 0.45) / 0.2, 0, 1)
    const punchStart = 0.65
    const punchStep = 0.08

    const titleWords = [
        "What",
        "if",
        "the",
        "picture",
        "could",
        "be",
        "drawn",
        "by",
        "everyone",
        "at",
        "once?",
    ]

    const punchlines = [
        { text: "A shared map.", offset: 0 },
        { text: "One picture.", offset: 1 },
        { text: "Built together.", offset: 2 },
    ]

    const css = `
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Fraunces:ital,wght@0,300;0,400;0,500;1,300;1,400;1,500&family=Poppins:wght@500;600;700&display=swap');

        @keyframes emergeGlow {
            0%, 100% { opacity: 0.55; }
            50% { opacity: 1; }
        }
    `

    const ringStyle = (scale: number, color: string, size: number): CSSProperties => ({
        position: "absolute",
        top: "50%",
        left: "50%",
        width: size,
        height: size,
        marginLeft: -size / 2,
        marginTop: -size / 2,
        borderRadius: "50%",
        border: `1px solid ${color}`,
        background: `radial-gradient(circle, ${color.replace(/[\d.]+\)$/, "0.18)")} 0%, transparent 72%)`,
        transform: `translate(-0%,-0%) scale(${scale})`,
        opacity: scale,
        transition: isStatic ? "none" : "transform 120ms linear",
        pointerEvents: "none",
    })

    return (
        <section
            ref={sectionRef}
            style={{
                position: "relative",
                width: "100%",
                minHeight: "180vh",
                background:
                    "radial-gradient(ellipse at 50% 50%, rgba(234,141,10,0.09) 0%, transparent 55%), linear-gradient(180deg, #08111c, #060a14)",
                color: "#f8fafc",
                overflow: "hidden",
                ...style,
            }}
        >
            <style>{css}</style>

            <div
                style={{
                    position: "sticky",
                    top: 0,
                    width: "100%",
                    height: "100vh",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    overflow: "hidden",
                }}
            >
                {/* grid bg */}
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        backgroundImage:
                            "linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px)",
                        backgroundSize: "72px 72px",
                        maskImage:
                            "radial-gradient(ellipse at center, black 20%, transparent 70%)",
                        pointerEvents: "none",
                    }}
                />

                {/* Concentric rings */}
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        pointerEvents: "none",
                    }}
                >
                    <div style={ringStyle(ring1, "rgba(234,141,10,0.45)", 1400)} />
                    <div style={ringStyle(ring2, "rgba(255,255,255,0.22)", 1000)} />
                    <div style={ringStyle(ring3, "rgba(19,136,8,0.45)", 640)} />

                    {/* core glow */}
                    <div
                        style={{
                            position: "absolute",
                            top: "50%",
                            left: "50%",
                            width: 260,
                            height: 260,
                            marginLeft: -130,
                            marginTop: -130,
                            borderRadius: "50%",
                            background:
                                "radial-gradient(circle, rgba(251,191,36,0.55) 0%, rgba(234,141,10,0.25) 40%, transparent 70%)",
                            transform: `scale(${0.3 + core * 0.8})`,
                            opacity: core,
                            filter: "blur(2px)",
                            transition: isStatic ? "none" : "transform 120ms linear",
                            pointerEvents: "none",
                            animation: inView
                                ? "emergeGlow 3.5s ease-in-out infinite"
                                : "none",
                        }}
                    />
                </div>

                {/* Content */}
                <div
                    style={{
                        position: "relative",
                        zIndex: 2,
                        width: "min(1100px, 100%)",
                        padding: "0 24px",
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                        textAlign: "center",
                        gap: 32,
                    }}
                >
                    {/* Eyebrow */}
                    <div
                        style={{
                            display: "inline-flex",
                            alignItems: "center",
                            gap: 12,
                            fontFamily: "'Inter', sans-serif",
                            fontSize: 11,
                            fontWeight: 700,
                            letterSpacing: "0.32em",
                            textTransform: "uppercase",
                            color: "#fbbf24",
                            opacity: Math.min(1, progress * 10),
                        }}
                    >
                        <span
                            style={{
                                width: 20,
                                height: 1,
                                background:
                                    "linear-gradient(90deg, transparent, rgba(234,141,10,0.9))",
                            }}
                        />
                        The Emergence
                        <span
                            style={{
                                width: 20,
                                height: 1,
                                background:
                                    "linear-gradient(90deg, rgba(234,141,10,0.9), transparent)",
                            }}
                        />
                    </div>

                    {/* Title — word reveal tied to progress */}
                    <h2
                        style={{
                            margin: 0,
                            fontFamily: "'Fraunces', serif",
                            fontWeight: 400,
                            fontSize: "clamp(32px, 5.5vw, 72px)",
                            lineHeight: 1.08,
                            letterSpacing: "-0.02em",
                            color: "#f8fafc",
                            maxWidth: 980,
                            perspective: 1000,
                            textShadow: "0 8px 40px rgba(0,0,0,0.5)",
                        }}
                    >
                        {titleWords.map((word, i) => {
                            const wordProgress = clamp(
                                titleReveal * titleWords.length - i,
                                0,
                                1
                            )
                            return (
                                <span
                                    key={`${word}-${i}`}
                                    style={{
                                        display: "inline-block",
                                        marginRight: "0.28em",
                                        opacity: wordProgress,
                                        transform: `translateY(${(1 - wordProgress) * 30}px)`,
                                        filter: `blur(${(1 - wordProgress) * 6}px)`,
                                        transition: isStatic
                                            ? "none"
                                            : "opacity 180ms, transform 180ms, filter 180ms",
                                    }}
                                >
                                    {word}
                                </span>
                            )
                        })}
                    </h2>

                    {/* Italic line */}
                    <div
                        style={{
                            fontFamily: "'Fraunces', serif",
                            fontStyle: "italic",
                            fontWeight: 300,
                            fontSize: "clamp(17px, 1.8vw, 22px)",
                            color: "rgba(226,232,240,0.82)",
                            maxWidth: 720,
                            opacity: italicReveal,
                            transform: `translateY(${(1 - italicReveal) * 18}px)`,
                            transition: isStatic
                                ? "none"
                                : "opacity 180ms, transform 180ms",
                        }}
                    >
                        Not a survey. Not a petition. Not another feed.
                    </div>

                    {/* Punchline stack */}
                    <div
                        style={{
                            marginTop: 12,
                            display: "flex",
                            flexDirection: "column",
                            gap: 4,
                            fontFamily: "'Poppins', sans-serif",
                            fontWeight: 700,
                            fontSize: "clamp(26px, 3.4vw, 44px)",
                            lineHeight: 1.15,
                            letterSpacing: "-0.025em",
                        }}
                    >
                        {punchlines.map((p, i) => {
                            const start = punchStart + i * punchStep
                            const pp = clamp((progress - start) / 0.08, 0, 1)
                            const color =
                                i === 0
                                    ? "#fbbf24"
                                    : i === 1
                                      ? "#f8fafc"
                                      : "#34c759"
                            return (
                                <div
                                    key={p.text}
                                    style={{
                                        color,
                                        opacity: pp,
                                        transform: `translateY(${(1 - pp) * 24}px)`,
                                        filter: `blur(${(1 - pp) * 5}px)`,
                                        textShadow:
                                            i === 0
                                                ? "0 0 30px rgba(234,141,10,0.4)"
                                                : i === 2
                                                  ? "0 0 30px rgba(19,136,8,0.4)"
                                                  : "0 8px 40px rgba(0,0,0,0.5)",
                                        transition: isStatic
                                            ? "none"
                                            : "opacity 200ms, transform 200ms, filter 200ms",
                                    }}
                                >
                                    {p.text}
                                </div>
                            )
                        })}
                    </div>

                    {/* Scroll hint when at top */}
                    <div
                        style={{
                            marginTop: 24,
                            fontFamily: "'Inter', sans-serif",
                            fontSize: 10,
                            fontWeight: 600,
                            letterSpacing: "0.4em",
                            textTransform: "uppercase",
                            color: "rgba(226,232,240,0.5)",
                            opacity: progress < 0.1 ? 1 : 0,
                            transition: "opacity 400ms",
                        }}
                    >
                        Scroll to reveal
                    </div>
                </div>
            </div>
        </section>
    )
}

addPropertyControls(ActEmergence, {})
",
  "exports": [
    {
      "name": "ActEmergence",
      "insertURL": "https://framer.com/m/ActEmergence-2TjrT8.js@FSckgfWD1jongzFwhcBh",
